-- 2321: calls go first, texts after (release 37). The owner, November 11: "The training for customer service and fleet and
-- basically anybody handling any calls ever should be that calls go first, texts go after. Its main priority is always to be
-- on the phone with people."
--   1. Academy: one section, "Calls first, texts after" (answer and return calls first, call before you text, a text is a
--      follow-up after a call attempt or what the person asked for; and the lead held on a call, 2320), on the customer
--      service, Fleet, Finance, both Sales paths and the Admin path. 90% pass mark unchanged. Staff who had passed every
--      section keep a week before the new section holds them (as 2151 did).
--   2. Guides: the same rule in the customer service, Fleet, Sales and Finance chapters, the texts and calls chapter, and
--      the Admin phone and leads chapters (the lead hold).
--   3. Unanswered lists missed calls (call-backs) above texts, the longest wait first in each.
create temp table r37calls_done on commit drop as
select distinct e.user_id from academy_enrollments e where app.academy_done(e.user_id);

-- ACADEMY 2321 START (generated by supabase/seed/2321_gen_academy.mjs from supabase/seed/academy/r37calls.mjs; do not edit by hand)
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r37-calls-first', 'Calls first, texts after', 'Your main priority is to be on the phone with people: answer and return calls first, call before you text, and a lead you handle on a call is yours for a while.', array['va/customer-service', 'va/fleet', 'va/sales', 'va/finance', 'admin/texts-and-calls-the-quo-phone-line', 'admin/leads-and-sales-claims']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 1, 'The phone comes first', '[{"caption":"The priority","say":"Anyone who handles calls has one main priority: to be on the phone with people. A ringing call is answered before anything else, and a missed call is returned at once.","visual":{"kind":"title","heading":"Calls first","text":"Be on the phone with people"}},{"caption":"Call, then text","say":"Call before you text. A text is a follow-up: after a call attempt that was not answered, or when the person asked for a text.","visual":{"kind":"steps","heading":"Reaching someone","items":["Call","No answer: leave a voicemail","Then send a text as the follow-up"]}},{"caption":"A text that was asked for","say":"If the person wrote that they prefer text, or asked you to text them, text them. That is their choice, and you may start with it.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Please text me, I cannot talk now."},{"who":"you","text":"Of course. Sending it by text now."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 2, 'On your screens', '[{"caption":"Call is first","say":"On every lead, renter and booking, Call is the first button and Text the second. The call opens through the site''s Call button, so it is noted on their history.","visual":{"kind":"list","heading":"Buttons","items":["Call first","Text second","Email third"]}},{"caption":"Your lists","say":"On your To do and on Unanswered, missed calls and call-backs are listed above unanswered texts. Work the list from the top.","visual":{"kind":"rule","heading":"The order","text":"Missed calls and call-backs, then texts.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 3, 'A lead on a call', '[{"caption":"The hold","say":"When customer service or Fleet answer or place a call with a lead, add a note on it or create it from a call, the lead is theirs for a limited time. Every call handled adds the time again.","visual":{"kind":"rule","heading":"Held for them","text":"About 15 minutes, and each handled call adds more.","tone":"ok"}},{"caption":"For Sales","say":"Sales see Being handled by, the first name and the function, with the time. They do not claim, call, text or email that lead, and Next lead skips it. It comes back when the time ends.","visual":{"kind":"rule","heading":"Leave it","text":"Being handled by Sam (Customer service).","tone":"warn"}},{"caption":"The booking","say":"A booking made from the lead is credited as always. Customer service and Fleet get no sales commission for it.","visual":{"kind":"rule","heading":"No change","text":"The commission rules stay as they are.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 1, 'A missed call and an unanswered text are both waiting. Which do you do first?', '["The text, it is faster","Call back the missed call","Whichever came in last","Neither until the end of the day"]'::jsonb, 1, 'Calls come first: return the missed call, then the text.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 2, 'You call a renter and they do not answer. What next?', '["Nothing more today","Leave a voicemail, then send a text as the follow-up","Text first next time","Close the task"]'::jsonb, 1, 'A text is the follow-up after a call attempt.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 3, 'When may a text come before a call?', '["Always, it is quicker","When the person asked for a text","When you are busy","Never"]'::jsonb, 1, 'If the person asked for a text, text them.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 4, 'Which button comes first on a lead or a renter?', '["Text","Email","Call","Note"]'::jsonb, 2, 'Call is the first button, Text the second.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 5, 'You answer a call with a lead. What happens to the lead?', '["Nothing","It is yours for a limited time, and Sales see who is handling it","It is closed","It goes to Sales at once"]'::jsonb, 1, 'It is held for you, and every call you handle adds time.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r37-calls-first'), 6, 'You are in Sales and a lead says Being handled by Sam (Customer service). What do you do?', '["Call it anyway","Text it, texts are allowed","Leave it: it returns when their time ends","Claim it"]'::jsonb, 2, 'You cannot claim, call, text or email it meanwhile.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
