-- Unanswered: missed calls (to call back) above texts
create function pg_temp.patch_fn(p_sig regprocedure, p_old text, p_new text) returns void
language plpgsql as $$
declare d text := pg_get_functiondef(p_sig);
begin
  if position(p_old in d) = 0 then raise exception '2321: the text to change was not found in %: %', p_sig, left(p_old, 120); end if;
  execute replace(d, p_old, p_new);
end $$;
select pg_temp.patch_fn('app.unanswered_view(uuid, jsonb)'::regprocedure,
  'order by u.waiting_since)', 'order by (u.kind <> ''missed_call''), u.waiting_since)');
